const ADMIN_SECTIONS=[
  {id:'Overview',label:'Overview',icon:NAV_ICONS.Dashboard},
  {id:'Groups',label:'Groups',icon:<svg {...ICON_PROPS}><circle cx="9" cy="9" r="2.8"/><circle cx="16" cy="10" r="2.2"/><path d="M4 19c.6-3 2.6-4.7 5-4.7s4.4 1.7 5 4.7M14.5 14.6c2 .3 3.4 1.7 3.9 4.4"/></svg>},
  {id:'Users',label:'Users & ceilings',icon:NAV_ICONS.Account},
  {id:'Effective',label:'Effective lookup',icon:<svg {...ICON_PROPS}><circle cx="10.5" cy="10.5" r="6"/><path d="M15 15l5.5 5.5"/></svg>},
  {id:'Presets',label:'Mode presets',icon:<svg {...ICON_PROPS}><path d="M4 7h16M4 12h16M4 17h16"/><circle cx="9" cy="7" r="1.6" fill="currentColor" stroke="none"/><circle cx="16" cy="12" r="1.6" fill="currentColor" stroke="none"/><circle cx="11" cy="17" r="1.6" fill="currentColor" stroke="none"/></svg>},
  {id:'Owners',label:'Owner access',icon:<svg {...ICON_PROPS}><path d="M12 3l7 3v5c0 5-3 8.5-7 10-4-1.5-7-5-7-10V6z"/></svg>},
  {id:'Wallets',label:'Batch import',icon:NAV_ICONS.Wallets},
];
const ADMIN_SLUGS={Overview:'',Groups:'groups',Users:'users',Effective:'effective',Presets:'presets',Owners:'owners',Wallets:'wallets'};
const SLUG_ADMIN_SECTIONS=Object.fromEntries(Object.entries(ADMIN_SLUGS).map(([section,slug])=>[slug,section]));
function adminSectionFromLocation(){const segment=window.location.pathname.replace(/^\/dashboard\/admin\/?/,'').replace(/\/+$/,'');return SLUG_ADMIN_SECTIONS[segment]||'Overview';}
const ADMIN_MOBILE_PRIMARY=['Overview','Groups','Users'];
const ADMIN_MOBILE_MORE=['Effective','Presets','Owners','Wallets'];
function AdminNav({page,go}){return <nav aria-label="Admin sections" className="rail-main-nav"><ul>{ADMIN_SECTIONS.map(section=><li key={section.id}><button aria-current={page===section.id?'page':undefined} onClick={()=>go(section.id)}><span className="nav-icon" aria-hidden="true">{section.icon}</span><span className="nav-label">{section.label}</span></button></li>)}</ul></nav>}
function AdminBottomBar({page,go,moreOpen,onOpenMore}){return <nav className="mobile-bottombar admin-mobile-bottombar" aria-label="Admin primary">{ADMIN_MOBILE_PRIMARY.map(id=>{const item=ADMIN_SECTIONS.find(section=>section.id===id);return <button key={id} type="button" aria-current={page===id?'page':undefined} onClick={()=>go(id)}><span className="nav-icon" aria-hidden="true">{item.icon}</span><span className="nav-label">{item.label}</span></button>})}<button type="button" aria-current={moreOpen||ADMIN_MOBILE_MORE.includes(page)?'page':undefined} onClick={onOpenMore}><span className="nav-icon" aria-hidden="true">{MORE_ICON}</span><span className="nav-label">More</span></button></nav>}
function AdminMoreSheet({open,page,go,onClose,onLogout}){return <>{open&&<div className="sheet-backdrop" onClick={onClose}/>}<div className={`more-sheet admin-more-sheet${open?' open':''}`} role="dialog" aria-modal="true" aria-label="More admin pages" aria-hidden={!open}><button type="button" className="sheet-handle" aria-label="Close" onClick={onClose}/><h2>More admin pages</h2><div className="sheet-grid">{ADMIN_MOBILE_MORE.map(id=>{const item=ADMIN_SECTIONS.find(section=>section.id===id);return <button type="button" key={id} aria-current={page===id?'page':undefined} onClick={()=>go(id)}><span className="nav-icon" aria-hidden="true">{item.icon}</span><span className="nav-label">{item.label}</span></button>})}</div><div className="admin-sheet-actions"><a className="quiet admin-link" href="/dashboard/">Back to user dashboard</a><button className="quiet" onClick={onLogout}>Log out</button></div></div></>}
function ScrollTop(){const [visible,setVisible]=useState(false);useEffect(()=>{const update=()=>setVisible(window.scrollY>480);update();window.addEventListener('scroll',update,{passive:true});return()=>window.removeEventListener('scroll',update);},[]);return visible?<button type="button" className="scroll-top" aria-label="Scroll to top" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}>↑</button>:null;}
function AdminShell({profile,onLogout}){const theme=profile.theme||'ghost-mint';const [page,setPage]=useState(adminSectionFromLocation());const [moreOpen,setMoreOpen]=useState(false);const [railExpanded,setRailExpandedState]=useState(readRailExpanded);function setRailExpanded(next){setRailExpandedState(value=>{const resolved=typeof next==='function'?next(value):next;writeRailExpanded(resolved);return resolved;});}const live=useLiveSocket();useEffect(()=>{document.documentElement.dataset.theme=theme;},[theme]);useEffect(()=>{function onPopState(){setPage(adminSectionFromLocation());}window.addEventListener('popstate',onPopState);return()=>window.removeEventListener('popstate',onPopState);},[]);if(!profile.isOwner)return <AdminDenied/>;function go(next){const slug=ADMIN_SLUGS[next];const path=slug?`/dashboard/admin/${slug}`:'/dashboard/admin';if(window.location.pathname!==path)window.history.pushState(null,'',path);setPage(next);setMoreOpen(false);window.scrollTo({top:0});}const brandMark=<span className="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d={BOLT_PATH} fill="currentColor"/></svg></span>;return <div className={`shell rail-shell admin-shell${moreOpen?' more-open':''}`} data-rail={railExpanded?'expanded':'collapsed'}><ConfirmHost/><ToastHost/><header className="rail-mobile-header"><a className="brand" href="/dashboard/admin" onClick={event=>{event.preventDefault();go('Overview');}}>{brandMark}GhostMint Admin</a><div className="header-right"><span className="status-pill"><span className={`status-dot${live?' live':''}`} aria-hidden="true"/><span aria-live="polite">{live?'Live':'Connecting'}</span></span><NotificationBell/><a className="header-avatar" aria-label="Return to user dashboard" href="/dashboard/">{NAV_ICONS.Account}</a></div></header><aside><div className="rail-top"><a className="brand" href="/dashboard/admin" onClick={event=>{event.preventDefault();go('Overview');}}>{brandMark}<span className="nav-label">GhostMint Admin</span></a></div><AdminNav page={page} go={go}/><nav className="rail-bottom-nav" aria-label="Admin account"><ul><li><a className="admin-rail-link" href="/dashboard/"><span className="nav-icon" aria-hidden="true">{CHEVRON_LEFT}</span><span className="nav-label">User dashboard</span></a></li><li><button onClick={onLogout}><span className="nav-icon" aria-hidden="true">{NAV_ICONS.Account}</span><span className="nav-label">Log out</span></button></li></ul></nav></aside><button type="button" className="rail-edge-toggle" aria-label={railExpanded?'Collapse sidebar':'Expand sidebar'} onClick={()=>setRailExpanded(value=>!value)}>{railExpanded?CHEVRON_LEFT:CHEVRON_RIGHT}</button><div className="notification-bell-desktop"><NotificationBell/></div><main className="content admin-content" tabIndex="-1"><Admin profile={profile} section={page} go={go}/></main><AdminBottomBar page={page} go={go} moreOpen={moreOpen} onOpenMore={()=>setMoreOpen(value=>!value)}/><AdminMoreSheet open={moreOpen} page={page} go={go} onClose={()=>setMoreOpen(false)} onLogout={onLogout}/><ScrollTop/></div>;}
function isAdminPath(){const path=window.location.pathname.replace(/\/+$/,'');return path==='/dashboard/admin'||path.startsWith('/dashboard/admin/');}
export default function App(){const [profile,setProfile]=useState(undefined);const [,forceRender]=useState(0);useEffect(()=>{api('/api/profile').then(setProfile).catch(()=>setProfile(null));},[]);useEffect(()=>{function onPopState(){forceRender(count=>count+1);}window.addEventListener('popstate',onPopState);return()=>window.removeEventListener('popstate',onPopState);},[]);async function logout(){await api('/api/auth/logout',{method:'POST'});setProfile(null);}if(profile===undefined)return <main className="loading" aria-live="polite">Loading secure session...</main>;if(!profile)return <Login onLogin={setProfile}/>;if(isAdminPath())return <AdminShell profile={profile} onLogout={logout}/>;return <Shell profile={profile} onLogout={logout} onProfileChange={setProfile}/>;}